// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5).
// SOS light: fast blink x3 (150/150 ms), 1 s pause, slow blink x2 (600/600 ms), loop.
// Hardware: GPIO4 -> 220R (r1) -> led1 anode (A); led1 cathode (K) -> J1_GND4 (GND).
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include "esp_timer.h"

#define SOS_LED_GPIO GPIO_NUM_4

static inline void led_on(void)
{
    gpio_set_level(SOS_LED_GPIO, 1);
}

static inline void led_off(void)
{
    gpio_set_level(SOS_LED_GPIO, 0);
}

static void blink(int times, int on_ms, int off_ms)
{
    for (int i = 0; i < times; i++) {
        led_on();
        vTaskDelay(pdMS_TO_TICKS(on_ms));
        led_off();
        vTaskDelay(pdMS_TO_TICKS(off_ms));
    }
}

void app_main(void)
{
    gpio_config_t io = {
        .pin_bit_mask = 1ULL << SOS_LED_GPIO,
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    gpio_config(&io);

    led_off(); // power-on default: LED dark

    printf("PlugAI SOS light: GPIO%d, fast x3 (150/150 ms), 1 s pause, slow x2 (600/600 ms), loop\n",
           (int)SOS_LED_GPIO);

    while (1) {
        blink(3, 150, 150);          // fast three flashes: 900 ms
        vTaskDelay(pdMS_TO_TICKS(1000)); // pause: dark (150 ms tail + 1000 ms = 1150 ms)
        blink(2, 600, 600);          // slow two flashes: 2400 ms
        printf("SOS cycle done\n");  // one line per cycle (evidence only)
    }
}
